function outputFile = generateCudaGeometryReferenceFixtures(outputFile)
%GENERATECUDAGEOMETRYREFERENCEFIXTURES Generate CUDA geometry references.
%   Run this function on a Windows machine with an NVIDIA GPU after
%   compiling the CUDA backend. CudaGeometryReferenceTest consumes the
%   resulting MAT file.

if nargin == 0
    outputFile = fullfile(fileparts(mfilename('fullpath')), ...
        'cuda_geometry_reference.mat');
end

matlabRoot = fileparts(fileparts(fileparts(mfilename('fullpath'))));
repositoryRoot = fileparts(matlabRoot);
addpath(matlabRoot);
InitTIGRE('backend', 'cuda');

fixture = struct;
fixture.schemaVersion = 1;
fixture.metadata = struct( ...
    'matlabVersion', version, ...
    'computer', computer, ...
    'mexExtension', mexext, ...
    'gpuNames', {getGpuNames()}, ...
    'sourceVersion', sourceVersion(repositoryRoot), ...
    'sourceStatus', sourceStatus(repositoryRoot));

inputs = geometryCases();
caseNames = fieldnames(inputs);
fixture.cases = struct;
gpuIds = GpuIds();

for caseIndex = 1:numel(caseNames)
    caseName = caseNames{caseIndex};
    caseData = inputs.(caseName);
    interpolated = Ax( ...
        caseData.image, caseData.geometry, caseData.angles, ...
        'interpolated', 'gpuids', gpuIds);
    siddon = Ax( ...
        caseData.image, caseData.geometry, caseData.angles, ...
        'Siddon', 'gpuids', gpuIds);
    caseData.cuda = struct( ...
        'interpolated', interpolated, ...
        'siddon', siddon, ...
        'fdk', Atb( ...
            interpolated, caseData.geometry, caseData.angles, ...
            'FDK', 'gpuids', gpuIds), ...
        'matched', Atb( ...
            interpolated, caseData.geometry, caseData.angles, ...
            'matched', 'gpuids', gpuIds));
    fixture.cases.(caseName) = caseData;
end

validateCudaGeometryReferenceFixture(fixture);
save(outputFile, 'fixture', '-v7');
fprintf('CUDA geometry reference fixture written to %s\n', outputFile);
end

function cases = geometryCases()
[image, geometry, alpha] = baseData('cone');

staticOrigin = geometry;
staticOrigin.offOrigin = [0.8; -0.6; 0.4];

perViewOrigin = geometry;
perViewOrigin.offOrigin = [ ...
    0.8 * sin(alpha); ...
    0.6 * cos(alpha); ...
    linspace(-1, 1, numel(alpha))];

staticDetector = geometry;
staticDetector.offDetector = [1.25; -0.75];

perViewDetector = geometry;
perViewDetector.offDetector = [ ...
    1.2 * sin(alpha); 0.7 * cos(alpha)];

staticCor = geometry;
staticCor.COR = 0.35;

perViewCor = geometry;
perViewCor.COR = 0.3 * sin(alpha);

detectorRoll = geometry;
detectorRoll.rotDetector = [ ...
    0.08 * sin(alpha); zeros(2, numel(alpha))];

detectorPitch = geometry;
detectorPitch.rotDetector = [ ...
    zeros(1, numel(alpha)); ...
    0.06 * cos(alpha); ...
    zeros(1, numel(alpha))];

detectorYaw = geometry;
detectorYaw.rotDetector = [ ...
    zeros(2, numel(alpha)); 0.07 * sin(2 * alpha)];

arbitraryAngles = [ ...
    alpha; 0.1 * sin(alpha); 0.06 * cos(alpha)];

helical = geometry;
helical.offOrigin = zeros(3, numel(alpha));
helical.offOrigin(3, :) = linspace(-2, 2, numel(alpha));

varyingDistances = geometry;
varyingDistances.DSO = 40 + 1.2 * sin(alpha);
varyingDistances.DSD = 60 + 1.5 * cos(alpha);

[dbtImage, dbtGeometry, dbtAngles] = dbtData();

combinedCone = geometry;
combinedCone.offOrigin = [ ...
    0.7 * sin(alpha); ...
    0.5 * cos(alpha); ...
    linspace(-1.5, 1.5, numel(alpha))];
combinedCone.offDetector = [ ...
    1.1 * sin(alpha); 0.8 * cos(alpha)];
combinedCone.COR = 0.2 * sin(alpha);
combinedCone.rotDetector = [ ...
    0.07 * sin(alpha); ...
    0.05 * cos(alpha); ...
    0.06 * sin(2 * alpha)];
combinedCone.DSO = 40 + sin(alpha);
combinedCone.DSD = 60 + cos(alpha);

[parallelImage, combinedParallel, parallelAlpha] = baseData('parallel');
parallelAngles = [ ...
    parallelAlpha; ...
    0.08 * sin(parallelAlpha); ...
    0.05 * cos(parallelAlpha)];
combinedParallel.offOrigin = [ ...
    0.6 * sin(parallelAlpha); ...
    0.4 * cos(parallelAlpha); ...
    linspace(-1, 1, numel(parallelAlpha))];
combinedParallel.offDetector = [ ...
    0.9 * sin(parallelAlpha); 0.6 * cos(parallelAlpha)];
combinedParallel.COR = 0.15 * sin(parallelAlpha);
combinedParallel.rotDetector = [ ...
    0.05 * sin(parallelAlpha); ...
    0.04 * cos(parallelAlpha); ...
    0.03 * sin(2 * parallelAlpha)];
combinedParallel.DSO = 40 + 0.8 * sin(parallelAlpha);
combinedParallel.DSD = 60 + 0.9 * cos(parallelAlpha);

cases = struct( ...
    'originOffsetStatic', referenceCase(image, staticOrigin, alpha), ...
    'originOffsetPerView', referenceCase(image, perViewOrigin, alpha), ...
    'detectorOffsetStatic', referenceCase(image, staticDetector, alpha), ...
    'detectorOffsetPerView', ...
        referenceCase(image, perViewDetector, alpha), ...
    'corStatic', referenceCase(image, staticCor, alpha), ...
    'corPerView', referenceCase(image, perViewCor, alpha), ...
    'detectorRoll', referenceCase(image, detectorRoll, alpha), ...
    'detectorPitch', referenceCase(image, detectorPitch, alpha), ...
    'detectorYaw', referenceCase(image, detectorYaw, alpha), ...
    'arbitraryAngles', ...
        referenceCase(image, geometry, arbitraryAngles), ...
    'helical', referenceCase(image, helical, alpha), ...
    'varyingDistances', ...
        referenceCase(image, varyingDistances, alpha), ...
    'staticDetectorDbt', ...
        referenceCase(dbtImage, dbtGeometry, dbtAngles), ...
    'combinedCone', ...
        referenceCase(image, combinedCone, arbitraryAngles), ...
    'combinedParallel', ...
        referenceCase(parallelImage, combinedParallel, parallelAngles));
end

function value = referenceCase(image, geometry, angles)
value = struct( ...
    'image', image, ...
    'geometry', geometry, ...
    'angles', angles);
end

function [image, geometry, angles] = baseData(mode)
geometry = fixtureGeometry([12; 11; 9], [14; 11], mode);
angles = linspace(0, 2 * pi, 7);
angles(end) = [];
image = fixturePhantom(geometry.nVoxel);
end

function [image, geometry, angles] = dbtData()
geometry = fixtureGeometry([10; 12; 8], [14; 10], 'cone');
geometry.DSO = 50;
geometry.DSD = 65;
geometry.offOrigin = [2; 0; 1];
geometry.offDetector = [0; 2];
angles = linspace(-pi / 12, pi / 12, 7);
geometry = staticDetectorGeo(geometry, angles);
image = fixturePhantom(geometry.nVoxel);
end

function geometry = fixtureGeometry(nVoxel, nDetector, mode)
geometry = defaultGeometry( ...
    'nVoxel', nVoxel, 'nDetector', nDetector, 'mode', mode);
geometry.nVoxel = double(nVoxel);
geometry.nDetector = double(nDetector);
geometry.sVoxel = double(nVoxel);
geometry.dVoxel = geometry.sVoxel ./ geometry.nVoxel;
geometry.dDetector = [1; 1];
geometry.sDetector = geometry.nDetector .* geometry.dDetector;
geometry.DSO = 40;
geometry.DSD = 60;
geometry.accuracy = 0.5;
end

function image = fixturePhantom(dimensions)
[x, y, z] = ndgrid( ...
    linspace(-1, 1, dimensions(1)), ...
    linspace(-1, 1, dimensions(2)), ...
    linspace(-1, 1, dimensions(3)));
image = single((x.^2 + 1.2 * y.^2 + 0.8 * z.^2) < 0.55);
end

function value = sourceVersion(repositoryRoot)
[status, output] = system(sprintf( ...
    'git -C "%s" rev-parse HEAD', repositoryRoot));
if status == 0
    value = strtrim(output);
else
    value = 'unavailable';
end
end

function value = sourceStatus(repositoryRoot)
[status, output] = system(sprintf( ...
    'git -C "%s" status --short', repositoryRoot));
if status ~= 0
    value = 'unavailable';
elseif isempty(strtrim(output))
    value = 'clean';
else
    value = strtrim(output);
end
end
